ryan: Py sketch:
```python
import time, random, requests
def retry_get(u, attempts=3, base=0.1):
  for i in range(attempts):
    try: return requests.get(u, stream=True, timeout=10)
    except requests.RequestException:
      if i==attempts-1: raise
      time.sleep(base*(2**i)+random.random()*base)
```

priya: TS sketch:
```ts
async function* streamLines(url:string,cursor?:string){
  const u=new URL(url); if(cursor) u.searchParams.set('cursor',cursor);
  const r=await fetch(u.toString()); if(!r.body) return;
  const reader=r.body.getReader(); const dec=new TextDecoder(); let buf='';
  while(true){const {done,value}=await reader.read(); if(done) break; buf+=dec.decode(value,{stream:true}); let nl; while((nl=buf.indexOf('\n'))>=0){yield buf.slice(0,nl); buf=buf.slice(nl+1);} }
  if(buf) yield buf;
}
```

